"""Генерирует tests/tasks.jsonl — локальный «скрытый набор» с эталонными решениями.
Дополняйте своими заданиями: текст + эталонная программа (проверяется refgeom)."""
import json
T = []
def add(text, ops): T.append({"id": f"t{len(T)+1:02d}", "text": text, "gold": {"ops": ops}})

add("Шайба: наружный диаметр 24 мм, внутренний диаметр 13 мм, толщина 2,5 мм.",
    [{"op":"extrude","sketch":[{"type":"circle","d":24},{"type":"circle","d":13}],"depth":2.5}])
add("Пластина 100 × 60 × 5 мм с шестью сквозными отверстиями диаметром 4,5 мм, расположенными в два ряда по три. Шаг отверстий 40 мм вдоль длинной стороны, расстояние между рядами 40 мм; группа отверстий расположена по центру пластины.",
    [{"op":"extrude","sketch":[{"type":"rect","w":100,"h":60}],"depth":5},{"op":"holes","d":4.5,"pattern":{"type":"grid","nx":3,"ny":2,"dx":40,"dy":40}}])
add("Вал ступенчатый: первая ступень диаметром 25 мм и длиной 20 мм, вторая — диаметром 20 мм и длиной 50 мм, третья — диаметром 16 мм и длиной 30 мм.",
    [{"op":"shaft","steps":[{"d":25,"l":20},{"d":20,"l":50},{"d":16,"l":30}]}])
add("Втулка с буртом: наружный диаметр втулки 22 мм, общая длина 30 мм. На одном конце бурт диаметром 32 мм и толщиной 5 мм (входит в общую длину). Сквозное осевое отверстие диаметром 14 мм.",
    [{"op":"shaft","steps":[{"d":32,"l":5},{"d":22,"l":25}],"bore_d":14}])
add("Квадратный фланец 60 × 60 мм толщиной 8 мм с центральным отверстием диаметром 25 мм и четырьмя отверстиями диаметром 6,6 мм по углам; межосевые расстояния угловых отверстий 46 × 46 мм.",
    [{"op":"extrude","sketch":[{"type":"rect","w":60,"h":60},{"type":"circle","d":25}],"depth":8},{"op":"holes","d":6.6,"pattern":{"type":"rect","w":46,"h":46}}])
add("Крышка: диск диаметром 70 мм и толщиной 6 мм. Шесть сквозных отверстий диаметром 5,5 мм равномерно на окружности диаметром 56 мм. В центре с одной стороны глухое отверстие диаметром 20 мм и глубиной 3 мм.",
    [{"op":"extrude","sketch":[{"type":"circle","d":70}],"depth":6},{"op":"holes","d":5.5,"pattern":{"type":"circular","pcd":56,"n":6}},{"op":"holes","d":20,"points":[[0,0]],"offset":6,"direction":"-","depth":3}])
add("Брусок 50 × 40 × 30 мм. Сквозное отверстие диаметром 12 мм проходит через центры граней 50 × 40.",
    [{"op":"extrude","sketch":[{"type":"rect","w":50,"h":40}],"depth":30},{"op":"holes","d":12,"points":[[0,0]]}])
add("Пластина 80 × 40 × 6 мм с продольным сквозным пазом шириной 10 мм; полная длина паза 50 мм, концы паза скруглены, паз расположен по центру пластины вдоль длинной стороны.",
    [{"op":"extrude","sketch":[{"type":"rect","w":80,"h":40},{"type":"slot","length":50,"width":10}],"depth":6}])
add("Уголок равнополочный: ширина полок 30 мм, толщина 3 мм, длина 100 мм.",
    [{"op":"extrude","plane":"XZ","sketch":[{"type":"polygon","points":[[0,0],[30,0],[30,3],[3,3],[3,30],[0,30]]}],"depth":100}])
add("Швеллер: ширина 60 мм, высота полок 30 мм, толщина стенки и полок 4 мм, длина 80 мм.",
    [{"op":"extrude","plane":"XZ","sketch":[{"type":"polygon","points":[[0,0],[60,0],[60,30],[56,30],[56,4],[4,4],[4,30],[0,30]]}],"depth":80}])
add("Шестигранная втулка: размер под ключ 22 мм, длина шестигранной части 25 мм. С одного торца соосно цилиндрический хвостовик диаметром 16 мм и длиной 10 мм. Через всю деталь проходит осевое отверстие диаметром 12 мм.",
    [{"op":"extrude","sketch":[{"type":"hexagon","s":22}],"depth":25},{"op":"extrude","sketch":[{"type":"circle","d":16}],"offset":25,"depth":10},{"op":"holes","d":12,"points":[[0,0]]}])
add("Г-образный кронштейн шириной 40 мм из пластин толщиной 5 мм: длина основания 60 мм, общая высота 50 мм, вертикальная стенка примыкает к короткому краю основания. В основании два сквозных отверстия диаметром 8 мм: центры на расстоянии 35 мм от наружной поверхности стенки, межосевое расстояние 20 мм, симметрично по ширине.",
    [{"op":"extrude","plane":"XZ","sketch":[{"type":"polygon","points":[[0,0],[60,0],[60,5],[5,5],[5,50],[0,50]]}],"depth":40,"direction":"both"},{"op":"holes","d":8,"points":[[35,-10],[35,10]]}])
add("Цилиндр диаметром 40 мм и высотой 30 мм. С верхнего торца соосно глухое отверстие диаметром 20 мм и глубиной 18 мм. Поперёк цилиндра на высоте 10 мм от нижнего торца — сквозное отверстие диаметром 8 мм, проходящее через ось.",
    [{"op":"shaft","steps":[{"d":40,"l":30}]},{"op":"holes","d":20,"points":[[0,0]],"offset":30,"direction":"-","depth":18},{"op":"holes","plane":"XZ","d":8,"points":[[0,10]]}])
add("Пластина 70 × 30 × 4 мм. Все четыре угла пластины в плане срезаны фасками 5 × 45°.",
    [{"op":"extrude","sketch":[{"type":"polygon","points":[[-30,-15],[30,-15],[35,-10],[35,10],[30,15],[-30,15],[-35,10],[-35,-10]]}],"depth":4}])
add("Плита 40 × 40 × 12 мм с четырьмя отверстиями под винты М6: сквозное отверстие диаметром 6,6 мм с цилиндрической цековкой диаметром 11 мм и глубиной 6,5 мм с верхней стороны. Межосевые расстояния отверстий 28 × 28 мм, по центру плиты.",
    [{"op":"extrude","sketch":[{"type":"rect","w":40,"h":40}],"depth":12},{"op":"holes","d":6.6,"pattern":{"type":"rect","w":28,"h":28},"offset":12,"cbore_d":11,"cbore_depth":6.5}])

if __name__ == "__main__":
    import os
    from agent.dsl import normalize
    from agent.refgeom import measure
    with open(os.path.join(os.path.dirname(__file__), "tasks.jsonl"), "w", encoding="utf-8") as f:
        for t in T:
            m = measure(normalize(t["gold"]))
            t["expected"] = {"volume": round(m["volume"], 3), "bbox_sorted": [round(x, 4) for x in m["bbox_sorted"]]}
            f.write(json.dumps(t, ensure_ascii=False) + "\n")
            print(t["id"], t["expected"])
